/bin/zsh -lc "python3 - <<'PY'
from pathlib import Path
import json, hashlib, collections
for p in sorted(Path('programs/absys/absys').glob('P12*')):
 print(p.name, '\\n'+'\\n'.join(l.split('%')[0].strip() for l in p.read_text().splitlines() if l.split('%')[0].strip()))
 for c in ['absys-depth-first','absys-wake-back']:
  assert p.read_bytes()==(Path('programs/absys')/c/p.name).read_bytes()
print('ALL THREE CONFIGURATIONS HAVE IDENTICAL SOURCE BYTES')
for p in sorted(Path('results/absys/logs').glob('*P12*')):
 lines=p.read_text().splitlines(); print('LOG',str(p),len(lines),collections.Counter(l.split('\\t')[-2] if len(l.split('\\t'))==7 else l.split('\\t')[-1] for l in lines))
for f in ['results/absys/batch-log.tsv','results/absys/rerun-m2-log.tsv']:
 p=Path(f)
 print('P12 rows',f,[l for l in p.read_text().splitlines() if '\\tP12' in l] if p.exists() else 'absent')
x=json.loads(Path('harnesses/stages.json').read_text());print('STAGES keys',list(x));
for k,v in x.items():
 if k=='problems':
  if isinstance(v,dict): print(json.dumps(v.get('P12'),indent=2))
  else: print(json.dumps([p for p in v if p.get('id')=='P12'],indent=2))
PY"

